// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Receiver rec;

    function setUp() public { 
        c = new airPort();
        rec = new Receiver();
    }

    // fuzzed params: from address, value v, and an array of single recipient addresses
    // We restrict _tos to length==1 via the fuzzed parameter bytes32 singleTo to avoid needing accumulation
    function testFuzz_property(address from, uint256 v, bytes32 singleTo) public {
        // keep fuzz domain wide but ensure non-zero-length _tos as required by contract
        address to = address(uint160(uint256(singleTo)));
        address[] memory tos = new address[](1);
        tos[0] = to;

        // The contract C makes low-level calls to caddress with selector transferFrom(address,address,uint256)
        // We deploy a Receiver that implements that function and ALWAYS returns successfully.
        // Use its address as caddress so the calls succeed; the reference implementation returns true
        // whenever the call sequence completes. The mutant returns false, so we assert the call returns true.

        bool ok;
        try c.transfer(from, address(rec), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // would mean revert; reference should not revert for these inputs
        }

        // The universal property: for any admissible input (non-empty tos), the reference returns true.
        // The mutant (returning false) will cause this assertion to fail for some inputs the fuzzer finds.
        assertTrue(ok);
    }
}

// A minimal recording/receiving helper that matches the selector used by C:
// function transferFrom(address,address,uint256)
contract Receiver {
    event Called(address from, address to, uint256 v);

    // exact signature so C's abi.encodeWithSelector invokes this function
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        emit Called(from, to, v);
        return true;
    }
}
